window.FILM_WORK_PROMPTS={"work_id":"src-747ec6a746d5bd9c","records":[{"work_id":"src-747ec6a746d5bd9c","frame_id":"FG-03384ed68e1a9359","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/07 (434).jpg","source_page":"https://film-grab.com/2014/06/02/hanna/","scene":"画面主体为一名浅色卷发人物的面部特写，人物面朝右前方，背景为模糊的暖褐色环境，整体呈现昏暗的橙黄色调。","analysis":"人物面部占据画面左侧约三分之一区域，右侧为大面积虚化的背景。光线从右前方照射，在人物面部形成强烈的明暗对比，高光集中在额头、鼻梁和脸颊，阴影深邃。背景呈现模糊的土黄色块，无法辨认具体物体，营造出一种封闭、压抑且温暖的氛围。","prompt":"昏暗环境下的浅色卷发人物面部特写，人物面朝右前方，眼神专注。强烈的暖橙色侧光从右前方打在脸上，照亮额头、鼻梁和脸颊，形成鲜明的明暗对比，阴影深邃。背景为大面积虚化的土黄色块，模糊不清，营造出封闭且压抑的氛围。画面色调统一为暖褐色，质感细腻，具有电影感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T13:04:07-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/07 (434).jpg","observed_dimensions":[1280,528],"source_thumbnail_dimensions":[500,206],"source_image_match_mae":0.48,"observed_resolution":"normal","observation_limits":[],"id":"VP-f30e3ca7a8ffe503","origin":"visual"},{"work_id":"src-747ec6a746d5bd9c","frame_id":"FG-33e5c06d4507ec05","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/20 (443).jpg","source_page":"https://film-grab.com/2014/06/02/hanna/","scene":"一位红发女性位于画面中央，手托下巴，目光向上凝视。背景昏暗，左右两侧各有一个模糊的人影，整体环境幽暗封闭。","analysis":"画面采用中心构图，主体人物占据画面中央约三分之一区域，清晰可见其头部及肩部以上。背景左右两侧各有一个模糊的人影，形成对称的视觉平衡。光线柔和地打在主体面部，与周围深暗的环境形成对比，营造出一种静谧而略带神秘的氛围。","prompt":"画面中央是一位红发女性的半身像，她身穿深色西装外套，内搭浅色衣物，右手手指轻触下巴，眼神向上方凝视，神情专注。背景处于昏暗的室内环境中，左右两侧各有一个模糊的人影，左侧人影头发较长，右侧人影头发较短，均穿着深色衣物。整体色调偏冷，光线主要集中在中央女性面部，背景细节隐没在阴影中，呈现出一种电影般的质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T13:04:13-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/20 (443).jpg","observed_dimensions":[1280,528],"source_thumbnail_dimensions":[500,206],"source_image_match_mae":0.504,"observed_resolution":"normal","observation_limits":[],"id":"VP-d481d71d8b857188","origin":"visual"},{"work_id":"src-747ec6a746d5bd9c","frame_id":"FG-33e1f29b67b77c3f","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/33 (441).jpg","source_page":"https://film-grab.com/2014/06/02/hanna/","scene":"画面右侧可见一名金发人物的面部局部，仅露出右眼、鼻梁及部分额头，其余部分隐没在黑暗背景中，环境几乎全黑。","analysis":"构图极度偏右，人物面部占据画面右半部分，左侧大面积留黑。仅可见人物右眼、眉毛、鼻梁及额头局部，视线向右侧凝视。光线从右侧微弱照亮面部，形成强烈的明暗对比，皮肤纹理清晰，发丝在光线下呈现金黄色，整体色调冷峻压抑。","prompt":"画面右侧特写一名金发人物的面部局部，仅露出右眼、眉毛、鼻梁及部分额头，其余部分隐没在黑暗背景中。人物视线向右侧凝视，眼神专注。光线从右侧微弱照亮面部，形成强烈的明暗对比，皮肤纹理清晰，发丝在光线下呈现金黄色。左侧大面积留黑，环境几乎全黑，整体色调冷峻压抑，营造出一种窥视或紧张的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T13:04:20-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/33 (441).jpg","observed_dimensions":[1280,528],"source_thumbnail_dimensions":[500,206],"source_image_match_mae":0.525,"observed_resolution":"normal","observation_limits":[],"id":"VP-fbb276c2f9330c2b","origin":"visual"},{"work_id":"src-747ec6a746d5bd9c","frame_id":"FG-bf7aee28971b6086","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/46 (429).jpg","source_page":"https://film-grab.com/2014/06/02/hanna/","scene":"画面主体为女性面部下半部分与手持镜子的反射影像。左侧是放大的嘴部特写，右侧是红发女性面部，背景为模糊的浅色墙面。","analysis":"构图采用左右分割，左侧占据约60%画面，展示极度放大的嘴部细节，牙齿间可见红色痕迹；右侧为红发女性面部，表情紧绷，眼神斜视。人物仅面部可见，无全身。光线柔和均匀，无明显阴影，色彩以肤色、红发和白色牙齿为主，镜框呈金属质感。","prompt":"画面左侧占据大部分空间，是一个极度放大的女性嘴部特写，嘴唇微张，露出整齐的白色牙齿，牙齿缝隙间有鲜红色痕迹，皮肤纹理清晰可见。画面右侧是一位红发女性的面部，她眼神斜向左侧，表情显得紧张或痛苦，嘴唇同样微张露出牙齿。中间有一个圆形的金属边框物体，可能是手持镜子，将左右两部分画面分隔开。背景为模糊的浅米色墙面，光线柔和均匀，整体色调偏暖，聚焦于面部细节和表情张力。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T13:04:27-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/46 (429).jpg","observed_dimensions":[1280,528],"source_thumbnail_dimensions":[500,206],"source_image_match_mae":0.506,"observed_resolution":"normal","observation_limits":[],"id":"VP-799cfad545728c2c","origin":"visual"},{"work_id":"src-747ec6a746d5bd9c","frame_id":"FG-52e306efa51a009a","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/59 (390).jpg","source_page":"https://film-grab.com/2014/06/02/hanna/","scene":"昏暗环境中，一名长发人物面部及肩部可见，神情凝重，背景几乎全黑，仅见模糊的暗色轮廓。","analysis":"画面主体为人物面部与肩颈，占据画面中央偏左位置，背景大面积黑暗，仅右侧有微弱暗红轮廓。光线极暗，主要光源来自右上方，投射出紫红色调，照亮人物右侧脸颊与发丝，左侧面部及背景沉入阴影，明暗对比强烈，营造出压抑、神秘的视觉氛围。","prompt":"昏暗室内，一名长发人物面部及肩部清晰可见，神情凝重，目光直视前方。背景几乎全黑，仅右侧有模糊暗红轮廓。光线极暗，主要光源来自右上方，投射出紫红色调，照亮人物右侧脸颊与发丝，左侧面部及背景沉入阴影。人物轮廓柔和，发丝在光线下呈现微弱光泽，整体氛围压抑神秘，色彩以深红与暗紫为主，明暗对比强烈，细节隐没于黑暗中。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T13:04:33-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/59 (390).jpg","observed_dimensions":[1280,528],"source_thumbnail_dimensions":[500,206],"source_image_match_mae":0.401,"observed_resolution":"normal","observation_limits":[],"id":"VP-71ac0dae1f74ce42","origin":"visual"},{"work_id":"src-747ec6a746d5bd9c","frame_id":"FG-07eb1a621407edaf","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/08 (434).jpg","source_page":"https://film-grab.com/2014/06/02/hanna/","scene":"黄昏时分，巨大的太阳悬于地平线上方，前方是连绵的树林剪影。下方宽阔的水面平静如镜，倒映着天空的金黄与太阳的亮斑，前景左侧有两块深色岩石。","analysis":"画面采用水平分层构图，天空、树林剪影与水面各占约三分之一比例。太阳位于画面中轴线偏右位置，呈现高亮度的圆形光斑，与下方水面上的倒影形成垂直呼应。整体色调为深沉的橙黄色，光线从地平线处向四周辐射，前景岩石与树林呈现纯黑剪影，明暗对比强烈，营造出静谧而宏大的视觉氛围。","prompt":"黄昏时分的自然风景，巨大的太阳悬挂在低空，发出耀眼的橙黄色光芒。地平线上是一排茂密的针叶林剪影，树木轮廓清晰可见。下方是宽阔平静的水面，倒映着天空的金黄色调和太阳的圆形亮斑。前景左侧有两块深色的岩石露出水面，右侧边缘有少许树枝剪影。整体画面笼罩在浓郁的暖色调中，光线柔和而强烈，水面如镜，呈现出宁静而庄严的日落景象。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T14:06:21+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/08 (434).jpg","observed_dimensions":[1280,528],"source_thumbnail_dimensions":[500,206],"source_image_match_mae":0.512,"observed_resolution":"normal","observation_limits":[],"id":"VP-203e9897e697f8d2","origin":"visual"},{"work_id":"src-747ec6a746d5bd9c","frame_id":"FG-5b86d2eda3278f10","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/21 (443).jpg","source_page":"https://film-grab.com/2014/06/02/hanna/","scene":"巨大的灰绿色金属圆筒内部，一名身穿橙红色连体服的人物站立在右侧壁面，远处是封闭的横向格栅门，环境显得极度空旷。","analysis":"画面采用广角透视，巨大的圆筒结构占据绝大部分空间，形成强烈的纵深感。人物全身可见，位于画面右侧中景，与巨大的环境形成鲜明的大小对比。视角略微仰视，光线从右侧壁面的几处矩形灯具发出，照亮了人物和局部墙面，整体色调偏冷，与人物鲜艳的橙红色形成视觉反差。","prompt":"一张广角视角的科幻场景静帧，展示了一个巨大的灰绿色金属圆筒内部。圆筒壁面带有工业质感的纹理，右侧壁面上排列着几盏发光的矩形灯具，投射出冷白色的光线。在圆筒右侧的中景位置，一名身穿橙红色连体服的人物正站立在壁面上，全身可见，身形在巨大的空间中显得十分渺小。圆筒的尽头是一扇由横向金属条构成的封闭格栅门。整体画面色调偏冷，以灰绿色为主，人物的橙红色衣物成为画面中唯一的暖色焦点，营造出一种孤独、压抑且充满工业感的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T14:06:30+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/21 (443).jpg","observed_dimensions":[1280,528],"source_thumbnail_dimensions":[500,206],"source_image_match_mae":0.488,"observed_resolution":"normal","observation_limits":[],"id":"VP-e4aad42c7547d0e3","origin":"visual"},{"work_id":"src-747ec6a746d5bd9c","frame_id":"FG-22a7687933eef512","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/34 (441).jpg","source_page":"https://film-grab.com/2014/06/02/hanna/","scene":"巨大的圆形太阳悬于画面中央，左侧为深色山脊剪影，山脊线上分布着稀疏的树木轮廓，整体呈现橙黄色调的黄昏或黎明景象。","analysis":"构图上，山脊线从左下向右上倾斜，将画面分割为深色前景与明亮背景。太阳占据画面中心偏右位置，亮度极高，边缘清晰。山脊上的树木呈黑色剪影状，大小不一，沿山势分布。整体光线单一，色彩层次从中心的亮白过渡到四周的橙黄，对比强烈。","prompt":"画面呈现黄昏或黎明时分的自然景观，巨大的圆形太阳位于画面中央，发出耀眼的白光，周围天空呈现浓郁的橙黄色调。左侧是一道深黑色的山脊剪影，从左下角向右上角延伸，山脊轮廓起伏平缓。山脊线上散布着若干树木的黑色剪影，形态各异，有的呈团状，有的枝干分明。太阳部分被山脊遮挡，形成强烈的明暗对比。整体画面色调温暖，光影效果显著，营造出宁静而宏大的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T14:06:41+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/34 (441).jpg","observed_dimensions":[1280,528],"source_thumbnail_dimensions":[500,206],"source_image_match_mae":0.492,"observed_resolution":"normal","observation_limits":[],"id":"VP-acfd2c0b940530c1","origin":"visual"},{"work_id":"src-747ec6a746d5bd9c","frame_id":"FG-e14d515bda9ace06","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/47 (423).jpg","source_page":"https://film-grab.com/2014/06/02/hanna/","scene":"黄昏时分，一辆满载行李的白色面包车行驶在跨海大桥上，车内可见两名乘客，远处城市灯光与桥上路灯交织。","analysis":"画面采用低角度仰拍，面包车占据画面中心前景，车顶堆叠着大量行李。车内可见两名乘客的上半身轮廓，驾驶员位于左侧。背景是延伸向远方的桥梁，右侧路灯排列整齐，左侧远处是城市天际线。整体色调偏冷，以青绿色为主，天空呈现深蓝色与紫红色的渐变，车灯发出暖黄色光芒，形成冷暖对比。","prompt":"黄昏时分，一辆白色面包车行驶在跨海大桥上，车顶堆满了行李和包裹。车内可见两名乘客，驾驶员位于左侧，乘客坐在右侧，均可见上半身。车辆前大灯发出明亮的暖黄色光芒。桥梁向远方延伸，右侧排列着整齐的路灯，发出点点亮光。左侧远处是城市的天际线，隐约可见建筑轮廓和零星灯光。天空呈现深蓝色与紫红色的渐变，云层稀薄。整体色调偏冷，以青绿色为主，营造出一种旅途中的静谧氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T14:06:54+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/47 (423).jpg","observed_dimensions":[1280,528],"source_thumbnail_dimensions":[500,206],"source_image_match_mae":0.499,"observed_resolution":"normal","observation_limits":[],"id":"VP-453048dae9c73a3f","origin":"visual"},{"work_id":"src-747ec6a746d5bd9c","frame_id":"FG-057801af5a4dfa1a","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/60 (386).jpg","source_page":"https://film-grab.com/2014/06/02/hanna/","scene":"昏暗的室内空间，中央悬挂着一个人形轮廓，周围分布着多个形状怪异的柱状物体和碗状结构，地面有红色反光。","analysis":"画面采用中心构图，主体为中央倒挂的人形，仅可见躯干和腿部轮廓，头部细节模糊。周围物体呈对称分布，形成包围感。光线主要来自上方和地面的红色光源，整体色调偏暗，以红、黄为主，营造出压抑、诡异的氛围。","prompt":"昏暗的室内场景，中央倒挂着一个穿着深色衣物的人形轮廓，周围环绕着多个形状怪异的柱状物体，有的呈绿色，有的呈红色，形状类似生物肢体或抽象雕塑。地面反射着红色的光，中央下方有一个明亮的红色球状光源。整体色调偏暗，以红、黄、绿为主，光线从上方和地面投射，营造出压抑、诡异的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T14:07:07+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/60 (386).jpg","observed_dimensions":[1280,528],"source_thumbnail_dimensions":[500,206],"source_image_match_mae":0.424,"observed_resolution":"normal","observation_limits":[],"id":"VP-41bd43d457436c12","origin":"visual"}]};